#!/usr/bin/env python3
"""Generate/check the dependency strata of every public MuLIB header."""
import argparse
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parent.parent


def render():
    texts = {p.stem[6:]: p.read_text() for p in sorted((ROOT / 'include').glob('mulib-*.h'))}
    deps = {name: sorted(set(re.findall(r'^\s*#\s*include\s*["<]mulib-([^">]+)\.h[">]', text, re.M)))
            for name, text in texts.items()}
    # Collapse mutually reachable headers (legacy compatibility includes) into
    # one component before computing dependency layers.
    reach = {}
    for name in texts:
        found, todo = set(), [name]
        while todo:
            node = todo.pop()
            if node not in texts:
                raise ValueError('unknown module: ' + node)
            if node not in found:
                found.add(node)
                todo.extend(deps[node])
        reach[name] = found
    groups = {}
    for name in texts:
        groups[name] = tuple(n for n in sorted(reach[name]) if name in reach[n])
    layers = {}

    def visit(name):
        if name not in layers:
            group = groups[name]
            level = max((visit(d) + 1 for n in group for d in deps[n]
                         if d not in group), default=0)
            for n in group:
                layers[n] = level
        return layers[name]

    for name in texts:
        visit(name)
    lines = ['# MuLIB dependency strata', '',
             'Generated by `python3 tools/stratify.py`; verify with `--check`.', '',
             'A stratum is the longest dependency path from a header to a module with no',
             'MuLIB includes. Includes inside implementation sections count too. Mutually',
             'dependent compatibility headers form one group in a shared stratum.',
             'All dependencies outside a group must be in a lower stratum.',
             'These are integration layers, not standards-conformance or security ratings.', '',
             f'Inventory: {len(texts)} headers, {sum(len(d) for d in deps.values())} direct dependency edges.', '',
             'Define implementation switches for the full dependency closure in one translation',
             'unit. Headers never enable dependency implementations implicitly.', '']
    cycles = sorted(set(g for g in groups.values() if len(g) > 1))
    for group in cycles:
        lines += ['Compatibility group: ' + ', '.join('`' + n + '`' for n in group) + '.', '']
    for layer in sorted(set(layers.values())):
        names = [n for n in texts if layers[n] == layer]
        lines += [f'## Stratum {layer} ({len(names)} modules)', '',
                  '| Module | Direct dependencies |', '| --- | --- |']
        for name in names:
            dependencies = ', '.join('`' + d + '`' for d in deps[name]) or 'none'
            lines.append(f'| [{name}](mulib-{name}.md) | {dependencies} |')
        lines.append('')
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = ROOT / 'manual/strata.md'
    try:
        content = render()
        if args.check:
            if not target.exists() or target.read_text() != content:
                parser.exit(1, 'dependency strata are stale: run python3 tools/stratify.py\n')
        else:
            target.write_text(content)
    except ValueError as error:
        parser.exit(1, str(error) + '\n')
    print('MuLIB dependency strata: inventory and compatibility groups are current')


if __name__ == '__main__':
    main()
